// --- Clinic time formatting (presentation layer only; DB stores HH:mm) ---
const CLINIC_TIMEZONE = 'Asia/Karachi';

function parseClinicTime(raw) {
  if (raw == null || raw === '') return null;
  const s = String(raw).trim().replace(/\s+/g, ' ');
  const zone = CLINIC_TIMEZONE;
  const formats = ['HH:mm', 'H:mm', 'HH:mm:ss', 'H:mm:ss', 'h:mm a', 'h:mma', 'hh:mm a', 'hh:mma', 'h a', 'ha', 'h:mm:ss a'];
  for (const fmt of formats) {
    const dt = DateTime.fromFormat(s, fmt, { zone, locale: 'en' });
    if (dt.isValid) return dt;
  }
  const iso = DateTime.fromISO(s, { zone });
  if (iso.isValid && /T|\d:\d/.test(s)) return iso;
  return null;
}

function toStoredTime(raw) {
  const dt = parseClinicTime(raw);
  return dt ? dt.toFormat('HH:mm') : null;
}

function formatTime12h(raw) {
  const dt = parseClinicTime(raw);
  if (!dt) return raw;
  return dt.setLocale('en-US').toFormat('h:mm a').replace(/\b(am|pm)\b/gi, (m) => m.toUpperCase());
}

function clinicNow() {
  return DateTime.now().setZone(CLINIC_TIMEZONE);
}

function formatDateDisplay(isoOrDate) {
  const raw = String(isoOrDate || '').trim();
  const datePart = raw.includes('T') ? raw.split('T')[0] : raw.slice(0, 10);
  const dt = DateTime.fromISO(datePart, { zone: CLINIC_TIMEZONE });
  return dt.isValid ? dt.toFormat('MMMM d, yyyy') : raw;
}
// --- end clinic time formatting ---

const doctorItems = $('Get Doctor').all();
const doctor = doctorItems[0] ? doctorItems[0].json : null;
const trigger = $('Execute Workflow Trigger').first().json;

if (!doctor || !doctor.doctor_id) {
  return [{ json: { success: false, message: 'No doctor found with ID ' + trigger.doctor_id + '. Please check the doctor ID and try again.' } }];
}

const workingDays = (doctor.working_days || '').split(',').map(d => d.trim()).filter(Boolean);
const preferredDate = trigger.preferred_date;
const dt = DateTime.fromISO(preferredDate, { zone: CLINIC_TIMEZONE });

if (!dt.isValid) {
  return [{ json: { success: false, message: 'The date ' + preferredDate + ' is not valid. Please use YYYY-MM-DD format.' } }];
}

const weekdayMap = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
const weekdayName = weekdayMap[dt.weekday - 1];
const doctorLabel = doctor.doctor_name;
const dateDisplay = formatDateDisplay(preferredDate);

if (!workingDays.includes(weekdayName)) {
  return [{ json: { success: true, doctor_id: doctor.doctor_id, doctor_name: doctorLabel, date: preferredDate, date_display: dateDisplay, available_slots: [], available_slots_display: [], timezone: CLINIC_TIMEZONE, message: doctorLabel + ' does not work on ' + weekdayName + '. Working days are: ' + workingDays.join(', ') + '.' } }];
}

const [startStr, endStr] = (doctor.working_hours || '09:00-17:00').split('-');
const duration = doctor.slot_duration_minutes || 30;
let slotCursor = DateTime.fromFormat(startStr.trim(), 'HH:mm', { zone: CLINIC_TIMEZONE });
const end = DateTime.fromFormat(endStr.trim(), 'HH:mm', { zone: CLINIC_TIMEZONE });
const allSlots = [];
while (slotCursor < end) {
  allSlots.push(slotCursor.toFormat('HH:mm'));
  slotCursor = slotCursor.plus({ minutes: duration });
}

const bookedItems = $input.all();
const bookedTimes = bookedItems.map(i => toStoredTime(i.json.appointment_time)).filter(Boolean);
let availableSlots = allSlots.filter(s => !bookedTimes.includes(s));

const now = clinicNow();
const isToday = dt.hasSame(now, 'day');
let pastSlotsRemoved = false;
if (isToday) {
  const beforeCount = availableSlots.length;
  availableSlots = availableSlots.filter(s => {
    const slotDt = DateTime.fromFormat(s, 'HH:mm', { zone: CLINIC_TIMEZONE }).set({ year: now.year, month: now.month, day: now.day });
    return slotDt > now;
  });
  pastSlotsRemoved = availableSlots.length !== beforeCount;
}

const availableSlotsDisplay = availableSlots.map(formatTime12h);

let message;
if (availableSlots.length) {
  message = 'Available slots for ' + doctorLabel + ' on ' + dateDisplay + ': ' + availableSlotsDisplay.join(', ');
} else if (isToday && pastSlotsRemoved) {
  message = 'No more slots remaining today for ' + doctorLabel + '. Please try another date.';
} else {
  message = 'No slots available for ' + doctorLabel + ' on ' + dateDisplay + '. Please try another date.';
}

return [{ json: {
  success: true,
  doctor_id: doctor.doctor_id,
  doctor_name: doctorLabel,
  date: preferredDate,
  date_display: dateDisplay,
  timezone: CLINIC_TIMEZONE,
  available_slots: availableSlots,
  available_slots_display: availableSlotsDisplay,
  message: message
} }];
